import math
from fractions import Fraction


PI = 3.141592653589793


def subtract(a, b):
    return tuple(x - y for x, y in zip(a, b))


def cross(a, b):
    return (a[1] * b[2] - a[2] * b[1],
            a[2] * b[0] - a[0] * b[2],
            a[0] * b[1] - a[1] * b[0])


def dot(a, b):
    return sum(a[i] * b[i] for i in range(3))


def normal(face, points):
    a, b, c = (points[i] for i in face["vertices"])
    return cross(subtract(b, a), subtract(c, a))


def determinant(face, points):
    a, b, c = (points[i] for i in face["vertices"])
    return dot(a, cross(b, c))


def area(faces, points):
    total = 0.0
    for face in faces:
        n = normal(face, points)
        total += math.sqrt(dot(n, n))
    return total / 2


def triangle_angle(face, points):
    a, b, c = (points[i] for i in face["vertices"])
    products = (
        dot(subtract(b, a), subtract(c, a)),
        dot(subtract(c, b), subtract(a, b)),
        dot(subtract(a, c), subtract(b, c)),
    )
    smallest = min(products)
    return "obtuse" if smallest < 0 else "right" if smallest == 0 else "acute"


def edge_length_squared(edge, points):
    difference = subtract(points[edge[0]], points[edge[1]])
    return dot(difference, difference)


def winding_number(face_indices, faces, points, sample):
    total = 0.0
    for index in face_indices:
        a, b, c = [
            subtract(points[v], sample)
            for v in faces[index - 1]["vertices"]
        ]
        la = math.sqrt(dot(a, a))
        lb = math.sqrt(dot(b, b))
        lc = math.sqrt(dot(c, c))
        numerator = dot(a, cross(b, c))
        denominator = (
            la * lb * lc + dot(a, b) * lc
            + dot(b, c) * la + dot(c, a) * lb
        )
        total += 2 * math.atan2(numerator, denominator)
    return int(round(total / (4 * PI)))


def volume6(face_indices, faces, points):
    return sum(determinant(faces[index - 1], points) for index in face_indices)


def centroid(face_indices, faces, points, six_volume):
    coordinates = []
    for axis in range(3):
        numerator = 0
        for index in face_indices:
            face = faces[index - 1]
            signed = determinant(face, points)
            numerator += signed * sum(points[v][axis] for v in face["vertices"])
        coordinates.append(Fraction(numerator, 4 * six_volume))
    return tuple(coordinates)


def format_fraction(fraction):
    value = Fraction(fraction)
    if value.denominator == 1:
        return str(value.numerator)
    return f"{value.numerator}/{value.denominator}"


def format_real(value):
    result = f"{value:.3f}"
    return result[1:] if result.startswith("-") and float(result) == 0 else result


def bbox(vertices, points):
    locations = [points[i] for i in vertices]
    return (tuple(min(point[axis] for point in locations) for axis in range(3))
            + tuple(max(point[axis] for point in locations) for axis in range(3)))

import re
from pathlib import Path


INTEGER = re.compile(r"-?[0-9]+\Z")
IGNORED = {"vt", "vn", "s", "o", "usemtl", "mtllib"}


def integer_word(word):
    return INTEGER.fullmatch(word) is not None


def read_obj(path="input/model.obj"):
    lines = Path(path).read_text(encoding="ascii").splitlines()
    vertices = [None]
    polygons = []
    errors = []
    ignored = 0
    group = "default"
    for lineno, text in enumerate(lines, 1):
        if not text or text.startswith("#"):
            continue
        words = text.split(" ")
        command, args = words[0], words[1:]
        if command == "v":
            if len(args) != 3 or not all(integer_word(word) for word in args):
                errors.append((lineno, "bad_vertex"))
            else:
                vertices.append(tuple(map(int, args)))
        elif command == "f":
            if len(args) < 3:
                errors.append((lineno, "short_face"))
                continue
            resolved = []
            error = None
            for argument in args:
                vertex_part = argument.split("/", 1)[0]
                if not integer_word(vertex_part) or int(vertex_part) == 0:
                    error = "bad_index"
                    break
                number = int(vertex_part)
                if number < 0:
                    number = len(vertices) + number
                if not 1 <= number < len(vertices):
                    error = "out_of_range"
                    break
                resolved.append(number)
            if error:
                errors.append((lineno, error))
            else:
                polygons.append({
                    "number": len(polygons) + 1, "line": lineno,
                    "group": group, "vertices": tuple(resolved),
                })
        elif command == "g":
            group = args[0] if args else "default"
        elif command in IGNORED:
            ignored += 1
        else:
            errors.append((lineno, "unknown_keyword"))
    return {
        "lines": len(lines), "vertices": vertices,
        "polygons": polygons, "errors": errors, "ignored": ignored,
    }


def write_repaired_obj(vertices, faces):
    result = [
        f"# vertices {len(vertices) - 1} faces {len(faces)}"
    ]
    for point in vertices[1:]:
        result.append("v " + " ".join(map(str, point)))
    previous_group = None
    for face in faces:
        if face["group"] != previous_group:
            result.append("g " + face["group"])
            previous_group = face["group"]
        result.append("f " + " ".join(map(str, face["vertices"])))
    return result

from collections import deque

from topology import key_edge, triangle_edges


def has_directed(triangle, start, end):
    return (start, end) in triangle_edges(triangle)


def flip(face):
    a, b, c = face["vertices"]
    face["vertices"] = (a, c, b)


def inconsistent_edges(faces, edges):
    result = []
    for (a, b), adjacent in edges.items():
        if len(adjacent) != 2:
            continue
        first = has_directed(faces[adjacent[0] - 1]["vertices"], a, b)
        second = has_directed(faces[adjacent[1] - 1]["vertices"], a, b)
        if first == second:
            result.append((a, b))
    return result


def repair_orientation(faces, edges):
    adjacency = {}
    for edge, indices in edges.items():
        if len(indices) == 2:
            a, b = indices
            adjacency[(a, edge)] = b
            adjacency[(b, edge)] = a
    visited = set()
    for seed in range(1, len(faces) + 1):
        if seed in visited:
            continue
        visited.add(seed)
        queue = deque([seed])
        while queue:
            current = queue.popleft()
            for u, v in triangle_edges(faces[current - 1]["vertices"]):
                edge = key_edge(u, v)
                other = adjacency.get((current, edge))
                if other is None or other in visited:
                    continue
                if has_directed(faces[other - 1]["vertices"], u, v):
                    flip(faces[other - 1])
                visited.add(other)
                queue.append(other)


def orientable_components(faces, mesh):
    copied = [{**face} for face in faces]
    repair_orientation(copied, mesh["edges"])
    violations = inconsistent_edges(copied, mesh["edges"])
    return {
        comp["number"]: not any(edge in comp["edges"] for edge in violations)
        for comp in mesh["components"]
    }

from measure import cross, subtract


def split_polygons(polygons):
    triangles = []
    for polygon in polygons:
        corners = polygon["vertices"]
        for i in range(1, len(corners) - 1):
            triangles.append({
                "triangle": len(triangles) + 1,
                "polygon": polygon["number"],
                "line": polygon["line"],
                "group": polygon["group"],
                "vertices": (corners[0], corners[i], corners[i + 1]),
            })
    return triangles


def snapped_vertices(vertices, spacing):
    result = [None]
    changed = []
    for i, point in enumerate(vertices[1:], 1):
        rounded = tuple(
            spacing * ((2 * coordinate + spacing) // (2 * spacing))
            for coordinate in point
        )
        result.append(rounded)
        if rounded != point:
            changed.append((i, point, rounded))
    return result, changed


def representatives(points, merge):
    owner = {}
    result = [0]
    for i, point in enumerate(points[1:], 1):
        if not merge:
            result.append(i)
        else:
            owner.setdefault(point, i)
            result.append(owner[point])
    return result


def cleaned_faces(triangles, points, representative, remove_zero, remove_duplicate):
    faces = []
    removed = []
    seen = set()
    for triangle in triangles:
        a, b, c = (representative[v] for v in triangle["vertices"])
        reason = None
        if len({a, b, c}) < 3:
            reason = "repeated"
        elif remove_zero:
            p, q, r = points[a], points[b], points[c]
            if cross(subtract(q, p), subtract(r, p)) == (0, 0, 0):
                reason = "zero_area"
        if reason is None:
            identifier = tuple(sorted((a, b, c)))
            if remove_duplicate and identifier in seen:
                reason = "duplicate"
            else:
                seen.add(identifier)
        if reason is not None:
            removed.append({**triangle, "reason": reason})
        else:
            faces.append({**triangle, "vertices": (a, b, c)})
    return faces, removed


def remap_vertices(original, snapped, representative, faces, keep_unused):
    if keep_unused:
        present = {
            i for i in range(1, len(original))
            if representative[i] == i
        }
    else:
        present = {
            vertex for face in faces for vertex in face["vertices"]
        }
    old_numbers = sorted(present)
    new_numbers = {
        original_number: index
        for index, original_number in enumerate(old_numbers, 1)
    }
    points = [None] + [snapped[number] for number in old_numbers]
    mapped = [
        {**face, "vertices": tuple(new_numbers[v] for v in face["vertices"])}
        for face in faces
    ]
    return points, mapped, new_numbers


def fill_loops(faces, loops, max_length, permitted_components):
    added = []
    for loop in loops:
        loop["filled"] = False
        corners = loop["vertices"]
        length = loop["length"]
        if (loop["kind"] != "coherent" or not 3 <= length <= max_length
                or len(set(corners)) != length
                or loop["component"] not in permitted_components):
            continue
        for i in range(2, length):
            added.append({
                "triangle": None, "polygon": None, "line": None,
                "group": "fill",
                "vertices": (corners[0], corners[i], corners[i - 1]),
            })
        loop["filled"] = True
    return faces + added, added

from collections import defaultdict, deque


def triangle_edges(vertices):
    a, b, c = vertices
    return ((a, b), (b, c), (c, a))


def key_edge(a, b):
    return (min(a, b), max(a, b))


def edge_table(faces):
    result = defaultdict(list)
    for i, face in enumerate(faces, 1):
        for u, v in triangle_edges(face["vertices"]):
            result[key_edge(u, v)].append(i)
    return dict(sorted(result.items()))


def connected_components(faces, edges):
    neighbors = {i: set() for i in range(1, len(faces) + 1)}
    for adjacent in edges.values():
        for face in adjacent:
            neighbors[face].update(other for other in adjacent if other != face)
    unseen = set(neighbors)
    components = []
    while unseen:
        start = min(unseen)
        queue = deque([start])
        unseen.remove(start)
        component = []
        while queue:
            face = queue.popleft()
            component.append(face)
            for neighbor in sorted(neighbors[face]):
                if neighbor in unseen:
                    unseen.remove(neighbor)
                    queue.append(neighbor)
        components.append(sorted(component))
    return components


def vertex_fans(vertex, faces, edges):
    containing = [
        i for i, face in enumerate(faces, 1) if vertex in face["vertices"]
    ]
    others = set(containing)
    neighbors = defaultdict(set)
    for (u, v), participating in edges.items():
        if vertex not in (u, v):
            continue
        for first in participating:
            neighbors[first].update(
                second for second in participating if second != first
            )
    fans = []
    while others:
        seed = min(others)
        others.remove(seed)
        queue = deque([seed])
        part = []
        while queue:
            face = queue.popleft()
            part.append(face)
            for adjacent in sorted(neighbors[face]):
                if adjacent in others:
                    others.remove(adjacent)
                    queue.append(adjacent)
        fans.append(sorted(part))
    return fans


def analyze_mesh(faces):
    edges = edge_table(faces)
    face_components = connected_components(faces, edges)
    face_to_component = {}
    components = []
    for number, ids in enumerate(face_components, 1):
        for face_id in ids:
            face_to_component[face_id] = number
        vertices = sorted({
            v for face_id in ids for v in faces[face_id - 1]["vertices"]
        })
        component_edges = [
            edge for edge, adjacent in edges.items()
            if any(f in ids for f in adjacent)
        ]
        boundary = [edge for edge in component_edges if len(edges[edge]) == 1]
        nonmanifold = [edge for edge in component_edges if len(edges[edge]) >= 3]
        components.append({
            "number": number, "faces": ids, "vertices": vertices,
            "edges": component_edges,
            "boundary": boundary, "nonmanifold": nonmanifold,
        })
    used_vertices = sorted({
        v for face in faces for v in face["vertices"]
    })
    fans = {v: vertex_fans(v, faces, edges) for v in used_vertices}
    nonmanifold_vertices = sorted(v for v in fans if len(fans[v]) >= 2)
    for component in components:
        number = component["number"]
        component["nonmanifold_vertices"] = [
            v for v in component["vertices"]
            if sum(
                any(face_to_component[f] == number for f in fan)
                for fan in fans[v]
            ) >= 2
        ]
    return {
        "edges": edges, "components": components,
        "face_components": face_to_component,
        "fans": fans, "nonmanifold_vertices": nonmanifold_vertices,
    }


def boundary_loops(faces, mesh, contains_directed):
    loops = []
    edges = mesh["edges"]
    for component in mesh["components"]:
        component_number = component["number"]
        unused = set(component["boundary"])
        for first in sorted(component["boundary"]):
            if first not in unused:
                continue
            unused.remove(first)
            a, b = first
            sequence = [a, b]
            current = b
            while current != a:
                choices = [
                    (v if u == current else u, (u, v))
                    for u, v in unused if current in (u, v)
                ]
                if not choices:
                    break
                other, chosen = min(choices)
                unused.remove(chosen)
                sequence.append(other)
                current = other
            closed = sequence[-1] == a
            if not closed:
                kind = "open"
                length = len(sequence) - 1
            else:
                sequence.pop()
                length = len(sequence)
                directed = []
                for i in range(length):
                    u = sequence[i]
                    v = sequence[(i + 1) % length]
                    edge = key_edge(u, v)
                    face = faces[edges[edge][0] - 1]
                    directed.append(contains_directed(face["vertices"], u, v))
                if all(directed):
                    kind = "coherent"
                elif not any(directed):
                    kind = "coherent"
                    sequence = [sequence[0]] + list(reversed(sequence[1:]))
                else:
                    kind = "mixed"
            loops.append({
                "number": len(loops) + 1, "component": component_number,
                "vertices": sequence, "length": length,
                "kind": kind, "filled": False,
            })
    return loops
